import{_ as e,a as r,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"杀死一只知更鸟","description":"按31章阅读斯库特的成长、汤姆的审判和布·拉德利的故事，思考偏见与正义。","frontmatter":{"title":"杀死一只知更鸟","description":"按31章阅读斯库特的成长、汤姆的审判和布·拉德利的故事，思考偏见与正义。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 文学与人文社科 · 中外文学经典","summary":"按31章阅读斯库特的成长、汤姆的审判和布·拉德利的故事，思考偏见与正义。","status":"active","related":[{"title":"百年孤独","link":"/life/personal/books/humanities/one-hundred-years-of-solitude","kind":"书籍导读","scope":"general","audience":"general"},{"title":"一句顶一万句","link":"/life/personal/books/humanities/one-sentence-ten-thousand","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"百年孤独","link":"/life/personal/books/humanities/one-hundred-years-of-solitude"},"next":{"text":"一句顶一万句","link":"/life/personal/books/humanities/one-sentence-ten-thousand"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"百年孤独","link":"/life/personal/books/humanities/one-hundred-years-of-solitude"},"next":{"text":"一句顶一万句","link":"/life/personal/books/humanities/one-sentence-ten-thousand"}},"headers":[],"relativePath":"life/personal/books/humanities/to-kill-a-mockingbird.md","filePath":"life/personal/books/humanities/to-kill-a-mockingbird.md"}'),o={name:"life/personal/books/humanities/to-kill-a-mockingbird.md"};function n(i,t,l,s,h,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="杀死一只知更鸟" tabindex="-1">杀死一只知更鸟 <a class="header-anchor" href="#杀死一只知更鸟" aria-label="Permalink to &quot;杀死一只知更鸟&quot;">​</a></h1><p><strong>分类：文学与人文社科 → 中外文学经典。</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>哈珀·李的小说以美国南方小镇梅科姆为背景，由斯库特回望自己和哥哥杰姆的童年。父亲阿蒂克斯为遭到强奸指控的黑人汤姆·鲁滨逊辩护，使孩子逐渐看见熟悉社区内部的种族偏见、阶级差异和道德冲突。与此同时，他们一直好奇的邻居布·拉德利，也从恐怖传闻中的人物变成了需要重新理解的人。</p><p>小说把公共生活中的审判与日常交往中的误解放在一起。读者既可以关注证据如何被偏见压过，也可以观察儿童视角怎样修正对成年世界的理解。阅读时还应追问：谁拥有发言和解释的机会，谁的经验主要由别人转述？</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《杀死一只知更鸟》：作者为哈珀·李（Harper Lee）。</strong> <a href="https://www.arts.gov/initiatives/nea-big-read/kill-mockingbird" target="_blank" rel="noopener noreferrer">美国国家艺术基金会</a>介绍其阿拉巴马成长与写作背景；<a href="https://www.pulitzer.org/winners/harper-lee" target="_blank" rel="noopener noreferrer">普利策奖官方记录</a>确认本书获1961年小说奖。相关背景是美国南方生活经验与小说创作，审判场景服务于叙事，不能当作案件实录或今天的法律指南。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合从成长故事进入偏见、证据与公共正义议题的读者，也适合有讨论引导的青少年阅读。书中涉及种族歧视、性暴力指控与死亡，阅读前宜了解内容范围；历史知识应另配背景材料。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>原著为 <em>To Kill a Mockingbird</em>，1960 年出版，通行文本为两部分、31 章：第一部分第 1—11 章，第二部分第 12—31 章。中文版译者与 ISBN 尚未指定，人名译法可能不同。下表按通行编号导读，<strong>概括标题由本站拟定，不是原书章名</strong>，不对应某一译本的页码。</p><div class="warning custom-block"><p class="custom-block-title">剧透提示</p><p>下面介绍包括审判结果与结尾。希望保留初读体验时，可以只读已完成的章节。</p></div><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>本站概括与阅读重点</th></tr></thead><tbody><tr><td>1 · 认识梅科姆</td><td>斯库特介绍家人、小镇和迪尔，布·拉德利的传闻成为孩子们的好奇中心。开头以杰姆受伤引出整段回忆。</td></tr><tr><td>2 · 第一天上学</td><td>卡罗琳老师的教学方法与斯库特已有的阅读经验冲突。观察统一规则怎样忽略学生不同的家庭背景。</td></tr><tr><td>3 · 规则之外的人</td><td>沃尔特来家中吃饭，卡波妮与阿蒂克斯帮助斯库特理解别人；学校中的尤厄尔孩子也暴露了贫困与制度的关系。</td></tr><tr><td>4 · 树洞里的礼物</td><td>孩子发现树洞中出现物品，又把邻居的生活编成游戏。留意好奇与侵犯别人边界之间的距离。</td></tr><tr><td>5 · 传闻的另一面</td><td>莫迪小姐提供不同于街谈巷议的解释，孩子试图给布传递信息。判断人物之前，需要辨别消息来源。</td></tr><tr><td>6 · 夜探拉德利家</td><td>夜间窥探引起枪声，杰姆逃跑时丢下裤子。冒险的后果让他意识到自己并不真正了解对方。</td></tr><tr><td>7 · 被堵住的树洞</td><td>礼物持续出现，后来树洞被封住。通过杰姆的反应，观察一次无言交流被切断意味着什么。</td></tr><tr><td>8 · 雪与火</td><td>小镇罕见降雪，莫迪家失火；混乱中斯库特肩上多出一条毯子。照顾者可能正是被想象成可怕的人。</td></tr><tr><td>9 · 辩护带来的压力</td><td>案件影响孩子在学校和亲属中的处境。斯库特学习面对侮辱，也开始理解父亲为何坚持辩护。</td></tr><tr><td>10 · 疯狗与枪法</td><td>阿蒂克斯处理疯狗，孩子重新认识父亲。比较拥有力量与炫耀力量的区别。</td></tr><tr><td>11 · 杜博斯夫人</td><td>杰姆因破坏花木承担后果，后来理解老妇人的另一场斗争。勇气未必以胜利或讨人喜欢的形象出现。</td></tr><tr><td>12 · 卡波妮的教会</td><td>孩子参加黑人教会活动，看见社区互助及卡波妮在不同群体中的表达方式。一个人如何跨越不同生活世界？</td></tr><tr><td>13 · 亚历山德拉姑妈</td><td>姑妈来到家中，强调家世和得体的行为。比较她与阿蒂克斯对家庭责任的理解。</td></tr><tr><td>14 · 迪尔归来</td><td>家庭分歧加深，离家出走的迪尔出现在孩子身边。物质照料与被需要的感受并不相同。</td></tr><tr><td>15 · 监狱门前</td><td>阿蒂克斯面对聚集的人群，斯库特认出熟人并与他交谈。个人关系暂时打断了群体敌意。</td></tr><tr><td>16 · 进入法庭</td><td>审判吸引全镇关注，孩子坐到黑人旁听席。座位与围观本身也在展示社会秩序。</td></tr><tr><td>17 · 控方证词</td><td>警长与鲍勃·尤厄尔作证，伤势和惯用手成为细节线索。把事实、推断和缺失证据分开阅读。</td></tr><tr><td>18 · 梅耶拉作证</td><td>梅耶拉的孤立处境显现，阿蒂克斯质询指控中的矛盾。理解其处境不等于忽略指控给别人的伤害。</td></tr><tr><td>19 · 汤姆作证</td><td>汤姆叙述经历，他对梅耶拉的同情却触动种族等级禁忌。证词被怎样听见，受到权力关系影响。</td></tr><tr><td>20 · 法律与偏见</td><td>雷蒙德解释自己的伪装，阿蒂克斯作结案陈词。比较维持偏见的社会借口与法律宣称的平等。</td></tr><tr><td>21 · 裁决</td><td>陪审团作出有罪裁决，杰姆的信心受到打击。证明了疑点，并不意味着现实中必然获得公正结果。</td></tr><tr><td>22 · 判决之后</td><td>家庭与黑人社区回应审判，尤厄尔表达敌意。支持与善意不能抹去制度造成的损害。</td></tr><tr><td>23 · 解释不公</td><td>阿蒂克斯与孩子讨论陪审团、死刑和小镇阶层。杰姆对人的分类也在失望中改变。</td></tr><tr><td>24 · 客厅中的矛盾</td><td>姑妈的聚会显示体面言谈与本地偏见的反差，家中收到汤姆死亡的消息。礼仪能否容纳道德反省？</td></tr><tr><td>25 · 消息传播</td><td>汤姆之死在社区传播，报纸评论与日常闲谈给出不同解释。留意谁的判断被视为理所当然。</td></tr><tr><td>26 · 课堂里的双重标准</td><td>对远方迫害的谴责与小镇对本地黑人遭遇的态度形成对照，斯库特开始辨认这种矛盾。</td></tr><tr><td>27 · 敌意延续</td><td>尤厄尔继续表现怨恨，小镇筹备万圣节活动。此前的威胁成为结尾事件的背景。</td></tr><tr><td>28 · 回家路上</td><td>孩子在活动后遭到袭击，服装限制斯库特的视野。有限视角让读者与她一起拼接事件。</td></tr><tr><td>29 · 看见布</td><td>斯库特描述经过，终于认出屋中的布·拉德利。传闻人物与真实的人在此重合。</td></tr><tr><td>30 · 保护与公开</td><td>阿蒂克斯与警长讨论事件处理，牵涉责任、程序和无辜者的保护。结局留下值得讨论的伦理张力。</td></tr><tr><td>31 · 站在别人的门廊上</td><td>斯库特送布回家，从他的门前回望街道。换位理解成为重新组织经验的方式。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析，并非书单提供者的个人阅读记录。</strong> 小说没有让孩子因一次正确的辩护就生活在公平世界里。证据、勇气和善意都重要，却可能不足以扭转制度化偏见。由此需要继续追问：除了个人品格，还需要哪些公共制度与行动？</p><p>换位理解也不是替所有行为开脱。梅耶拉的脆弱、汤姆遭受的伤害和阿蒂克斯的选择，需要分别理解。把每个人看作具体的人，才可能兼顾同情、责任与事实。</p><p>读完可以比较两条线：布被社区如何讲述，汤姆在法庭上如何被听见？它们都涉及偏见，却有不同的社会后果，不能用一个温柔的结尾把两者化约成同一问题。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 理解一个人的处境，仍需要分别判断事实、责任与他受到的对待。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 把审判整理成证据表：谁说了什么，哪些是亲见，哪些是推断，哪些因偏见未被认真听见。再与布·拉德利的传闻对照，分析同是误解，为何有不同后果，练习检查来源与叙述权。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>儿童视角便于进入复杂道德议题，但黑人角色的经验较多由白人家庭转述，是值得追问的视角限制。个人善意不能完整解决制度问题。<strong>推荐语：</strong> 适合读后继续讨论，把温暖的私人理解与未解决的公共不公一起保留。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/To_Kill_a_Mockingbird" target="_blank" rel="noopener noreferrer">作品与出版背景</a>：核对作品身份与历史背景。</li><li><a href="https://www.sparknotes.com/lit/mocking/" target="_blank" rel="noopener noreferrer">SparkNotes 导读入口</a>：可按章节对照；本站表格为概括，不转载原文。</li><li><a href="https://search.worldcat.org/search?q=%E6%9D%80%E6%AD%BB%E4%B8%80%E5%8F%AA%E7%9F%A5%E6%9B%B4%E9%B8%9F" target="_blank" rel="noopener noreferrer">WorldCat 中文题名检索</a>：核对译者和中文版信息。</li></ul><p><a href="./../overview#humanities">返回书单总览</a></p>',27)])])}const k=e(o,[["render",n]]);export{u as __pageData,k as default};
